import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods

    /**
     * Allocates a new file inside {@code dir} with a unique name derived from {@code name}.
     * <p>
     * The method protects against directory‑traversal attacks by:
     * <ul>
     *   <li>Rejecting absolute paths.</li>
     *   <li>Normalising the resolved path and ensuring it stays within {@code dir}.</li>
     *   <li>Using {@link File#getCanonicalFile()} to resolve symbolic links and relative components.</li>
     * </ul>
     *
     * @param dir  the target directory (must exist or be creatable)
     * @param name the desired file name (may contain query parameters)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if the name is invalid or would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new NullPointerException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths – they would ignore the supplied directory
        if (new File(name).isAbsolute()) {
            throw new IllegalArgumentException("Absolute paths are not allowed");
        }

        try {
            // Resolve the base directory canonically
            File baseDir = dir.getAbsoluteFile();

            // Resolve the target file canonically
            File target = new File(baseDir, name).getCanonicalFile();

            // Ensure the target remains inside the base directory
            if (!target.getPath().startsWith(baseDir.getPath())) {
                throw new IllegalArgumentException(
                        "Path traversal detected: " + target.getPath());
            }

            // Prepare prefix/suffix for duplicate handling
            int dot = name.lastIndexOf('.');
            String prefix = dot < 0 ? name : name.substring(0, dot);
            String suffix = dot < 0 ? "" : name.substring(dot);

            // Find a unique filename
            File file = target;
            int index = 2;
            while (file.exists()) {
                file = new File(baseDir, prefix + "-" + index++ + suffix).getCanonicalFile();
                if (!file.getPath().startsWith(baseDir.getPath())) {
                    throw new IllegalArgumentException(
                            "Path traversal detected during renaming: " + file.getPath());
                }
            }

            // Create parent directories if necessary
            File parent = file.getParentFile();
            if (parent != null && !parent.exists()) {
                parent.mkdirs();
            }

            return file;
        } catch (IOException e) {
            throw new RuntimeException("Failed to allocate file", e);
        }
    }

    // other methods
}
