     * signature verification. Any algorithm outside this set will cause
     * the token to be rejected immediately. */
    private static final Set<String> ALLOWED_ALGORITHMS =
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "HS256", "HS384", "HS512",
                    "RS256", "RS384", "RS512",
                    "ES256", "ES384", "ES512"
