    private JWT decode(String encodedJWT, Header header, String[] parts, Verifier verifier) {

        // Reject unsigned tokens and any algorithm that is not explicitly whitelisted.
        String alg = header.algorithm.getName();
        if ("none".equalsIgnoreCase(alg)) {
            throw new MissingVerifierException(
                    "Unsigned JWTs are not permitted (algorithm='none')");
        }
        if (!ALLOWED_ALGORITHMS.contains(alg)) {
            throw new IllegalArgumentException(
                    "Unsupported JWT algorithm: " + alg);
        }

        // If a signature is present, a verifier must be supplied.
        if (parts.length == 3 && verifier == null) {
            throw new MissingVerifierException(
                    "No Verifier has been provided for verifying a signature signed using [" + alg + "]");
        }

        // If a verifier is supplied but the token contains no signature,
        // treat it as an invalid signature.
        if (parts.length == 2 && verifier != null) {
            throw new InvalidJWTSignatureException();
        }

        // The message comprises the first two segments of the entire JWT.
        int index = encodedJWT.lastIndexOf('.');
        byte[] message = encodedJWT.substring(0, index).getBytes(StandardCharsets.UTF_8);

        if (parts.length == 3) {
            // Verify the signature before deserializing the payload.
            byte[] signature = base64Decode(parts[2].getBytes(StandardCharsets.UTF_8));
            verifier.verify(header.algorithm, message, signature);
