private static String normalizePath(final String path) {
    if (path == null) {
        return null;
    }

    // Trim surrounding whitespace to avoid accidental mis‑parsing
    String s = path.trim();

    // Treat an empty path as the root path
    if (s.isEmpty()) {
        return "/";
    }

    // Collapse multiple leading slashes to a single slash
    int i = 0;
    while (i < s.length() && s.charAt(i) == '/') {
        i++;
    }
    if (i > 1) {
        s = s.substring(i - 1);
    }

    // Ensure the path starts with exactly one leading slash
    if (!s.startsWith("/")) {
        s = "/" + s;
    }

    return s;
}
