@Override
public ByteBuffer encode(final String name) {
    CharsetEncoder enc = newEncoder();
    // set actions to replace to avoid errors
    enc.onMalformedInput(java.nio.charset.CodingErrorAction.REPLACE);
    enc.onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPLACE);
