    int estimatedSize = estimateInitialBufferSize(enc, cb.remaining());
    ByteBuffer out = ByteBuffer.allocate(estimatedSize);
    while (cb.hasRemaining()) {
        CoderResult res = enc.encode(cb, out, false);
        if (res.isError()) {
            // Should not happen due to REPLACE, but guard
            res.throwException();
        }
        if (res.isOverflow()) {
            // grow buffer
            int newCapacity = out.capacity() * 2;
            ByteBuffer newOut = ByteBuffer.allocate(newCapacity);
            out.flip();
            newOut.put(out);
            out = newOut;
        }
    }
    // flush remaining
    CoderResult flushRes = enc.flush(out);
    while (flushRes.isOverflow()) {
        int newCapacity = out.capacity() * 2;
        ByteBuffer newOut = ByteBuffer.allocate(newCapacity);
        out.flip();
        newOut.put(out);
        out = newOut;
        flushRes = enc.flush(out);
    }
    if (flushRes.isError()) {
        flushRes.throwException();
    }
    out.flip();
    return out;
}
