    @Reference
    private SAXParserFactory factory;

    // other methods

    @Activate
    @SuppressWarnings("unused")
    protected void activate() {
        // Create a fresh factory instance and apply secure defaults
        factory = SAXParserFactory.newInstance();
        secureProcessing(factory);
        factory.setNamespaceAware(true);
        factory.setValidating(false);
    }

    /**
     * Configures the supplied {@link SAXParserFactory} to mitigate XXE attacks.
     *
     * @param factory the factory to configure
     */
    private static void secureProcessing(SAXParserFactory factory) {
        try {
            // Disallow DOCTYPE declarations entirely
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // Disable external general entities
