            // Prevent loading of external DTDs
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        } catch (ParserConfigurationException e) {
            // If the underlying parser does not support the requested features,
            // fail fast to avoid running with insecure defaults.
            throw new IllegalStateException("Failed to secure SAXParserFactory configuration", e);
        }
    }

    // other methods

}
