import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands the contents of an archive into {@code targetDirectory}.
     *
     * <p>All entry names are normalised and resolved against the target directory. Any attempt
     * to write outside the target directory (including via relative path components or
     * absolute paths) results in an {@link IOException}. The method also rejects entries
     * that resolve to a location that is not a descendant of the target directory after
     * canonicalisation, thereby preventing path‑traversal attacks.</p>
     *
     * @param supplier      provides the next readable entry from the archive
     * @param writer        writes the entry data to an {@link OutputStream}
     * @param targetDirectory the directory into which the archive should be expanded
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Canonical path of the target directory – used for all subsequent checks
        Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Skip empty or null entry names
            if (entryName == null || entryName.isEmpty()) {
                nextEntry = supplier.getNextReadableEntry();
                continue;
            }

            // Normalise the entry path to eliminate '.' and '..' components
            Path entryPath = Paths.get(entryName).normalize();

            // Reject absolute paths – they would escape the target directory
            if (entryPath.isAbsolute()) {
                throw new IOException("Entry name is absolute: " + entryName);
            }

            // Resolve the entry against the target directory and normalise again
            Path destPath = targetDirectory.toPath().resolve(entryPath).normalize();

            // Canonicalise the destination path to compare against the target directory
            Path canonicalDestPath = destPath.toFile().getCanonicalFile().toPath();

            // Verify that the destination is still within the target directory
            if (!canonicalDestPath.startsWith(canonicalTargetDir)) {
                throw new IOException("Expanding " + entryName + " would create file outside of "
                        + targetDirectory.getAbsolutePath());
            }

            if (nextEntry.isDirectory()) {
                // Create the directory (and any missing parents)
                Files.createDirectories(canonicalDestPath);
            } else {
                // Ensure parent directories exist
                Path parent = canonicalDestPath.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }

                // Write the file data
                try (OutputStream out = Files.newOutputStream(canonicalDestPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
