public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // other methods

    /**
     * Securely parses XML from various input types, preventing XXE attacks.
     */
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }
        Object answer = null;
        Class<?> type = getDocumentType();
        Exception cause = null;
        if (type != null) {
