/**
 * A custom codec that safely deserializes JSON arrays into Java arrays.
 *
 * <p>This implementation adds strict type validation and limits the size of
 * deserialized arrays to mitigate deserialization attacks that could arise
 * from older versions of Fastjson.</p>
 */
public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- */
    /* Configuration constants                                               */
    /* --------------------------------------------------------------------- */

    /** Maximum number of elements allowed in a deserialized array. */
    private static final int MAX_ARRAY_SIZE = 10_000;

    /** Set of component types considered safe for deserialization. */
    private static final Set<Class<?>> SAFE_TYPES = new HashSet<>(Arrays.asList(
            Boolean.class, Byte.class, Short.class, Integer.class, Long.class,
            Float.class, Double.class, Character.class,
            String.class, BigDecimal.class, BigInteger.class,
            Date.class, Calendar.class,
            LocalDate.class, LocalDateTime.class, ZonedDateTime.class
    ));

    /* --------------------------------------------------------------------- */
    /* Helper methods                                                       */
    /* --------------------------------------------------------------------- */

    /**
     * Checks whether a component type is allowed for deserialization.
     *
     * @param cls the component class to check
     * @return {@code true} if the class is considered safe
     */
    private static boolean isSafeComponent(Class<?> cls) {
        return cls.isPrimitive() || SAFE_TYPES.contains(cls);
    }

    /* --------------------------------------------------------------------- */
    /* Core deserialization logic                                           */
    /* --------------------------------------------------------------------- */

    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        /* Handle JSON null values early. */
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        /* Convert JSON string literals to byte arrays. */
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        /* Ensure the next token starts an array. */
        if (lexer.token() != JSONToken.LBRACKET) {
            throw new IllegalArgumentException(
                    "Expected JSON array start but found token: " + lexer.token());
        }

        /* Resolve the component type of the array. */
        Class<?> componentClass;
        Type componentType;

        if (type instanceof GenericArrayType) {
            GenericArrayType genericArray = (GenericArrayType) type;
            componentType = genericArray.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type contextType = parser.getContext().type;

                if (contextType instanceof ParameterizedType) {
                    ParameterizedType paramType = (ParameterizedType) contextType;
                    Type rawType = paramType.getRawType();
                    Type actualType = null;

                    if (rawType instanceof Class) {
                        TypeVariable<?>[] typeParams = ((Class<?>) rawType).getTypeParameters();
                        for (int i = 0; i < typeParams.length; ++i) {
                            if (typeParams[i].getName().equals(typeVar.getName())) {
                                actualType = paramType.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }

                    componentClass = (actualType instanceof Class)
                            ? (Class<?>) actualType
                            : Object.class;
                } else {
                    componentClass = TypeUtils.getClass(typeVar.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else {
            Class<?> clazz = (Class<?>) type;
            componentType = componentClass = clazz.getComponentType();
        }

        /* Validate the component type against the whitelist. */
        if (!isSafeComponent(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of array component type not allowed: "
                            + componentClass.getName());
        }

        /* Parse the JSON array into a JSONArray. */
        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        /* Enforce maximum array size to prevent OOM attacks. */
        if (array.size() > MAX_ARRAY_SIZE) {
            throw new IllegalArgumentException(
                    "Array size exceeds maximum allowed (" + MAX_ARRAY_SIZE + ")");
        }

        /* Convert JSONArray to a typed Java array. */
        Object[] resultArray = (Object[]) toObjectArray(parser, componentClass, array);

        /* Verify that each element matches the expected component type. */
        for (Object elem : resultArray) {
            if (elem != null && !componentClass.isInstance(elem)) {
                throw new IllegalArgumentException(
                        "Array element type mismatch: expected "
                                + componentClass.getName()
                                + " but found "
                                + elem.getClass().getName());
            }
        }

        return (T) resultArray;
    }

    /* --------------------------------------------------------------------- */
    /* Other methods (not shown)                                            */
    /* --------------------------------------------------------------------- */

    // ... existing serializer/deserializer methods ...
}
